<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      physical_attack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12.0</span></span>
